DROP DATABASE IF EXISTS arena_sports;
CREATE DATABASE arena_sports DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE arena_sports;

CREATE TABLE usuario (
    id_usuario     INT NOT NULL AUTO_INCREMENT,
    nome           VARCHAR(100) NOT NULL,
    telefone       VARCHAR(20)  NULL,
    login          VARCHAR(30)  NOT NULL,
    senha_hash     VARCHAR(200) NOT NULL,
    perfil         VARCHAR(15)  NOT NULL DEFAULT 'OPERADOR',
    ativo          TINYINT(1)   NOT NULL DEFAULT 1,
    PRIMARY KEY (id_usuario),
    UNIQUE KEY uk_usuario_login (login),
    CONSTRAINT ck_usuario_perfil CHECK (perfil IN ('ADMIN', 'OPERADOR'))
) ENGINE = InnoDB;

CREATE TABLE cliente (
    id_cliente     INT NOT NULL AUTO_INCREMENT,
    nome           VARCHAR(100) NOT NULL,
    telefone       VARCHAR(20)  NULL,
    email          VARCHAR(100) NULL,
    PRIMARY KEY (id_cliente),
    UNIQUE KEY uk_cliente_email (email)
) ENGINE = InnoDB;

CREATE TABLE categoria (
    id_categoria   INT NOT NULL AUTO_INCREMENT,
    nome           VARCHAR(50) NOT NULL,
    PRIMARY KEY (id_categoria),
    UNIQUE KEY uk_categoria_nome (nome)
) ENGINE = InnoDB;

CREATE TABLE produto (
    id_produto     INT NOT NULL AUTO_INCREMENT,
    nome           VARCHAR(100) NOT NULL,
    descricao      VARCHAR(200) NULL,
    preco          DECIMAL(10,2) NOT NULL,
    estoque        INT NOT NULL DEFAULT 0,
    codigo_barras  VARCHAR(18) NOT NULL,
    id_categoria   INT NOT NULL,
    PRIMARY KEY (id_produto),
    UNIQUE KEY uk_produto_codigo_barras (codigo_barras),
    CONSTRAINT ck_produto_preco   CHECK (preco >= 0),
    CONSTRAINT ck_produto_estoque CHECK (estoque >= 0),
    CONSTRAINT fk_produto_categoria
        FOREIGN KEY (id_categoria) REFERENCES categoria (id_categoria)
) ENGINE = InnoDB;

CREATE TABLE pedido (
    id_pedido      INT NOT NULL AUTO_INCREMENT,
    data_pedido    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    id_cliente     INT NOT NULL,
    id_usuario     INT NOT NULL,
    PRIMARY KEY (id_pedido),
    CONSTRAINT fk_pedido_cliente
        FOREIGN KEY (id_cliente) REFERENCES cliente (id_cliente),
    CONSTRAINT fk_pedido_usuario
        FOREIGN KEY (id_usuario) REFERENCES usuario (id_usuario)
) ENGINE = InnoDB;

CREATE TABLE item_pedido (
    id_pedido      INT NOT NULL,
    id_produto     INT NOT NULL,
    quantidade     INT NOT NULL,
    preco_unitario DECIMAL(10,2) NOT NULL,
    PRIMARY KEY (id_pedido, id_produto),
    CONSTRAINT ck_item_quantidade CHECK (quantidade > 0),
    CONSTRAINT fk_item_pedido
        FOREIGN KEY (id_pedido) REFERENCES pedido (id_pedido) ON DELETE CASCADE,
    CONSTRAINT fk_item_produto
        FOREIGN KEY (id_produto) REFERENCES produto (id_produto)
) ENGINE = InnoDB;


